import{_ as i,o as t,c as a,a2 as o}from"./chunks/framework.DwAI3uWn.js";const m=JSON.parse('{"title":"Individual Project Systems Feasibility Milestone","description":"PRELIMINARY EXAM: Individual\\nProject Systems Feasibility Milestone","frontmatter":{"title":"Individual Project Systems Feasibility Milestone","description":"PRELIMINARY EXAM: Individual\\nProject Systems Feasibility Milestone","source":"docs/archive/source-material/Individual Project Systems Feasibility Milestone.md","category":"Archive","sourceUpdated":"2026-10-08T06:33:54+08:00","outline":[2,3]},"headers":[],"relativePath":"content/docs/archive/source-material/individual-project-systems-feasibility-milestone.md","filePath":"content/docs/archive/source-material/individual-project-systems-feasibility-milestone.md"}'),n={name:"content/docs/archive/source-material/individual-project-systems-feasibility-milestone.md"};function r(s,e,l,p,d,c){return t(),a("div",null,[...e[0]||(e[0]=[o('<div><h1 id="document-title">Individual Project Systems Feasibility Milestone<a class="header-anchor" href="#document-title" aria-label="Link to title">​</a></h1><p>PRELIMINARY EXAM: Individual Project Systems Feasibility Milestone</p><p>Proposed Project:</p><p>Chainy: A 3D World Educational Game for learning emerging Technology</p><p>(Blockchain &amp; AI)</p><p>Group # 13</p><p>Sean Matthew Lee P. Narvaez</p><p>BSIT - GD J4S</p><p>PROFESSOR:</p><p>Grache Elizal C. Greta</p><p>P a g e | 1</p><p>University of Perpetual Help System Laguna - JONELTA</p><p>College of Computer Studies</p><p>Part I. Project Background and Problem Statement</p><ol><li>Project Title Chainy: A 3D World Educational Game for Learning Emerging</li></ol><p>Technology (Blockchain &amp; AI)</p><ol start="2"><li>Problem Statement</li></ol><p>Young learners have limited access to age-appropriate, safe, and engaging educational materials about emerging technologies such as blockchain and artificial intelligence (AI). Most existing learning resources rely on complex technical jargon or adult-oriented financial speculation. Additionally, unstable internet connectivity in underserved communities prevents continuous access to online educational platforms.</p><ol start="3"><li>Target Users</li></ol><p>Primary school children aged 6–12 years old (Kindergarten to Elementary / Grades 1 to 6) from Cryptita Plays outreach programs and community mini-library beneficiary sites.</p><ol start="4"><li><p>Purpose of the Proposed System To introduce foundational concepts of blockchain and artificial intelligence through an interactive 3D exploration and puzzle game. Learners explore a top-down 3D world with technology-building mechanics, accompanied by 2D/UI-driven mini-games for validation and classification. The system is built with a strictly offline-first architecture to run reliably on affordable mobile devices.</p></li><li><p>Reason Why the Problem Is Worth Solving</p></li></ol><p>Emerging technologies are transforming modern computing, yet young learners lack structured, age-appropriate foundations. By translating abstract concepts into gamified simulations, children develop early computational thinking and digital safety awareness without financial risk. Ensuring complete offline access on low-to-mid-range Android devices democratizes STEM education for underserved learners who lack consistent internet connectivity.</p><p>P a g e | 2</p><p>University of Perpetual Help System Laguna - JONELTA</p><p>College of Computer Studies</p><p>Guide Questions</p><ol><li>What problem does your proposed system aim to address? Chainy addresses the scarcity of age-appropriate, interactive educational resources that teach foundational blockchain and artificial intelligence concepts to young learners. Current introductory materials are overly technical and text-heavy, while dependency on continuous broadband internet access excludes students in resource-constrained communities from participating in digital education.</li><li>Who experiences this problem? The primary beneficiaries are children aged 6–12 years old within elementary schools, community mini-libraries, and Cryptita Plays educational outreach programs. Elementary educators and parents also experience this problem due to a lack of safe, non-speculative instructional tools for emerging technologies.</li><li>Why is this problem important? Foundational digital literacy must evolve alongside technological innovation. If young students are not introduced to the operational logic of distributed networks, data verification, and machine learning principles early on, the digital knowledge divide will widen, leaving them ill-prepared for future STEM and computational environments.</li><li>What is the main purpose of your proposed system? The main purpose of Chainy is to deliver an engaging, 3D game-based learning platform where young learners actively explore concepts through technology-building mechanics, transaction validation, tamper detection, pattern classification, and checkpoint quizzes.</li><li>Why should this project be considered for further development? Chainy presents a well-defined pedagogical scope, a clear target demographic, and an offline-first technical pipeline optimized for accessible mobile hardware. It bridges academic computer science principles with community outreach needs, providing a scalable prototype for early childhood technology literacy.</li></ol><p>Part II. Systems Thinking Analysis System Component</p><p>Description Based on the Proposed Project</p><p>User</p><p>Elementary students aged 6–12 years old from partner community mini-libraries and outreach programs.</p><p>Input</p><p>Multi-touch screen gestures: virtual joystick controls for 3D exploration, tap-to-interact triggers for objects/NPCs, drag-and-drop actions for sorting puzzles, and UI buttons for quiz answers.</p><p>P a g e | 3</p><p>University of Perpetual Help System Laguna - JONELTA</p><p>College of Computer Studies</p><p>Process</p><p>Unity C# game scripts process user input, execute character movement, manage 3D collision detection, validate puzzle states (e.g., hash matching, data sorting), compute quiz scores, and update player save states.</p><p>Output</p><p>Real-time top-down 3D visuals, animated characters, 2D UI puzzle overlays, visual verification cues, sound effects, background music, score tallies, and unlockable achievement badges.</p><p>Storage</p><p>Local Android internal storage containing pre-packaged 3D meshes, textures, audio assets, level definitions, and serialized JSON save files storing player progression, scores, and settings.</p><p>Hardware</p><p>Target Android mobile device equipped with an Octa-core CPU, minimum 4 GB RAM, minimum 64 GB storage, Mali-G57 or equivalent mobile GPU, touchscreen, and built-in speakers.</p><p>Operating System</p><p>Android 11 or newer, managing process scheduling, memory allocation, local file I/O, graphic rendering pipelines, audio output, and hardware touch input.</p><p>Network or Internet</p><p>Not required during standard gameplay. The entire educational curriculum, assets, and save systems run offline. Internet is utilized exclusively for initial APK installation or optional future updates.</p><p>Feedback or Result</p><p>Immediate audio-visual feedback on puzzle completion, visual indicators for block tamper detection, progress bar updates, stars/badges, and module completion summaries.</p><p>How do these components work together to make your proposed system function? Chainy operates as an integrated system where user touch inputs are captured by the Android OS and interpreted by Unity C# logic scripts to manipulate 3D game objects, UI states, and puzzle mechanics. The operating system allocates RAM and schedules CPU/GPU cycles to render low-poly 3D environments and process real-time game logic. In-game accomplishments dynamically trigger visual and auditory feedback, while player progress is automatically serialized to local JSON files. Because the system is architected as an offline-first application, all game assets and databases are self-contained on the device storage, ensuring a continuous learning loop that functions independently of external network infrastructure.</p><p>Part III. Target Platform and Hardware Requirements</p><ol><li>What is your target platform? Android smartphones and tablets.</li><li>Why is this platform appropriate for your target users? Android is the most widely adopted and economically accessible mobile operating system globally. It is prevalent in public schools, community mini-libraries, and low-to-middle-income</li></ol><p>P a g e | 4</p><p>University of Perpetual Help System Laguna - JONELTA</p><p>College of Computer Studies</p><p>households where dedicated gaming PCs or consoles are unavailable. Targeting Android maximizes the outreach potential of the educational software across diverse socioeconomic backgrounds. 3. Can your target users realistically access or use this platform? Yes. The project specifically targets children from outreach programs and mini-library beneficiary sites, so accessibility is one of the main considerations. Android smartphones and tablets are commonly available and may be personally owned, shared within families, or provided through schools, outreach programs, or beneficiary sites. Since prioritizing access to these shared or personal mobile devices is a recognized strategy for solving educational inequality (Alam &amp; Forhad, 2023), the project will also be optimized so that it does not require expensive hardware.</p><p>Component</p><p>Minimum Requirement</p><p>Recommended Requirement</p><p>Justification</p><p>CPU</p><p>Quad-core 2.0 GHz or equivalent</p><p>Octa-core 2.0 GHz or better</p><p>Needed for 3D game logic, player interaction, animations, educational activities, and background processes.</p><p>RAM 4 GB 6 GB or more</p><p>Provides enough memory for the 3D environment, textures, animations, audio, UI, and game logic.</p><p>Storage 2 GB free space</p><p>4 GB or more free space</p><p>Required for the game installation, 3D assets, textures, audio, lessons, mini-games, and offline educational content.</p><p>GPU</p><p>Adreno 506 / Mali-G57 or equivalent</p><p>Adreno 610 / Mali-G68 or better</p><p>Needed to render the game&#39;s 3D environments, models, textures, lighting, animations, and visual effects.</p><p>Input Device</p><p>Capacitive touchscreen</p><p>Multi-touch capacitive touchscreen</p><p>Used for movement, UI interaction, mini-games, puzzles, and menu controls.</p><p>Output Device</p><p>Smartphone/tablet display and speaker</p><p>HD display and built-in stereo speakers or headphones</p><p>Used to display the 3D environment and UI while providing music, instructions, and sound effects.</p><p>P a g e | 5</p><p>University of Perpetual Help System Laguna - JONELTA</p><p>College of Computer Studies</p><p>Internet Connection</p><p>Not required Not required</p><p>The core gameplay and educational content are designed to work offline.</p><p>Other Required Device</p><p>Not applicable Not applicable</p><p>Chainy does not require additional external hardware for its core features.</p><p>Guide Questions</p><ol><li>Why are these hardware requirements appropriate for your proposed system? They balance the visual and computational demands of a 3D game engine with the practical hardware profiles of budget Android devices found in community learning environments.</li><li>What may happen if the device does not meet the minimum requirements? The game may experience slow loading, lag, low frame rates, delayed responses, freezing, or crashes.</li><li>Are the hardware requirements realistic for your intended users? Yes. Modern budget Android devices released within the past several years typically feature at least 4 GB RAM and octa-core processors, making these specifications achievable.</li></ol><p>Part IV. Operating System Analysis</p><ol><li>What operating system will the proposed system support? Chainy will support the Android operating system, with Android 11 or newer as the target.</li><li>Why was this operating system chosen? Android was selected because Chainy is designed primarily for smartphones and tablets that are accessible to the target users. Android also provides the robust operating system services needed for application execution, memory management, file storage, touchscreen input, audio, security, and graphics processing (Ekanayake, 2018).</li><li>What operating system services will your proposed system use? Chainy will use process management, memory management, file management, device management, CPU scheduling, networking, and security and permissions to manage the game’s execution, resources, local files, hardware, and system access.</li></ol><p>OS Service How Chainy Will Use This Service Process Management</p><p>Android will manage the Chainy application process and coordinate it with other background applications running on the device.</p><p>P a g e | 6</p><p>University of Perpetual Help System Laguna - JONELTA</p><p>College of Computer Studies</p><p>Memory Management</p><p>Android will allocate and manage RAM used by the 3D environment, textures, animations, audio, UI elements, game logic, and educational activities.</p><p>File Management</p><p>The OS will manage access to installed game files, locally stored JSON save files, audio, 3D assets, textures, educational content, and other resources.</p><p>Device Management</p><p>Android will allow Chainy to communicate with the touchscreen, display, speakers, GPU, CPU, and other required device hardware.</p><p>CPU Scheduling</p><p>The OS will distribute CPU time between Chainy, system processes, and other applications so that the game can remain responsive.</p><p>Networking</p><p>Networking is not required for the core gameplay. Android networking services may only be used when downloading the game or receiving future application updates.</p><p>Security and Permissions</p><p>Android will provide application isolation, local file protection, and permissions needed to protect saved data and prevent unauthorized access to device resources.</p><p>Part V. Memory and Application Performance Planning</p><ol><li>What parts of the system may consume memory? The primary memory overhead in Chainy stems from the top-down 3D scene elements, particularly the character meshes, node/block prefabs, texture atlas sheets, and visual UI overlays. Secondary memory allocations include uncompressed audio streams for background music and interactive sound effects, active particle emitters for reward feedback, and runtime data structures used to track puzzle validation states</li><li>What resources will be loaded while the system is running? During an active session, the game engine loads the current level&#39;s 3D terrain geometry, player controller scripts, interactive building blocks, and sorting puzzle assets into volatile memory. It also holds the active HUD interface, audio playback clips, assessment quiz question structures, and the player&#39;s real-time progress buffer before it gets written to local storage</li><li>What could cause performance problems? Performance degradation can be triggered by rendering too many unbatched 3D objects at once, using high-resolution uncompressed textures, or running complex calculations inside per-frame update loops. Additionally, failing to clear previous scene assets during level transitions and forcing the mobile GPU to calculate dynamic real-time shadows will quickly overburden low-to-mid-range hardware.</li></ol><p>P a g e | 7</p><p>University of Perpetual Help System Laguna - JONELTA</p><p>College of Computer Studies</p><ol start="4"><li>What performance problems might users experience? Learners may encounter noticeable frame rate drops (stuttering below 30 FPS), delayed touch inputs when moving the character, extended scene loading times, device overheating, or sudden application crashes if the device runs out of available RAM.</li><li>How will performance problems be reduced? Chainy will use compressed and optimized 3D models, textures, images, and audio. Assets that are no longer needed will be unloaded instead of keeping the entire game in memory. The game will only load the necessary resources for the current area or activity.</li></ol><p>Possible Performance Concern</p><p>Possible Cause Proposed Solution</p><p>Slow loading</p><p>Large assets or too many resources loading at the same time.</p><p>Compress assets, organize scenes properly, and load only the resources required for the current area or activity.</p><p>High memory usage</p><p>Too many textures, models, audio files, animations, or unused game objects remaining in RAM.</p><p>Unload unused assets, reduce texture sizes, optimize 3D assets, and avoid loading the entire game at once.</p><p>Delayed response</p><p>Too many active objects, scripts, animations, physics calculations, or background processes.</p><p>Optimize C# scripts, reduce unnecessary calculations, simplify animations, and profile CPU usage.</p><p>Application freezing or crashing</p><p>Excessive RAM usage, unsupported hardware, or memory-heavy scenes.</p><p>Set asset limits, properly unload resources, test minimum-spec devices, and use Unity Profiler to identify memory problems.</p><p>Storage-related issue</p><p>Large offline assets, audio, textures, models, and educational content.</p><p>Compress files, use appropriate file formats, remove unused resources, and keep the installation size controlled.</p><p>Unstable or low frame rate</p><p>Too many 3D objects, large models, effects, lighting calculations, or animations.</p><p>Use optimized models, occlusion culling, simplified effects, quality settings, and frame-rate controls.</p><p>P a g e | 8</p><p>University of Perpetual Help System Laguna - JONELTA</p><p>College of Computer Studies</p><p>Part VI. Networking Requirement Analysis If your proposed system is offline, answer the following:</p><ol><li>Why does your system not require internet access? The entire core instructional pipeline of Chainy including the 3D top-down exploration worlds, technology-building mechanics, validation mini-games, and assessment quizzes is packaged directly within the local installation. Since the target learners in community mini-libraries and outreach centers may lack reliable or affordable Wi-Fi, the game is built to operate independently on local hardware to prevent connectivity-based interruptions.</li><li>What data or files will be stored locally? Game assets, educational content, settings, scores, completed activities, and player progress stored through JSON files will be kept locally.</li><li>What features could be added in the future that may require networking? Future features may include student analytics, downloadable educational content and updates, and integration with educational materials Offline Requirement</li></ol><p>Explanation</p><p>Reason for Offline Use</p><p>Chainy is intended to remain accessible even when the user does not have a stable internet connection. The main 3D exploration, lessons, puzzles, mini-games, and progress tracking do not require constant online communication.</p><p>Locally Stored Data</p><p>User settings, learning progress, completed activities, scores, game state, and other save information will be stored locally using JSON.</p><p>Local File or Storage Requirement</p><p>The device must have enough storage for the application, 3D models, textures, audio, animations, UI assets, educational materials, mini-games, and locally stored progress.</p><p>Possible Future Online Feature</p><p>Future versions could include game/content updates, optional student analytics, additional downloadable educational materials, or integration with partner organizations.</p><p>P a g e | 9</p><p>University of Perpetual Help System Laguna - JONELTA</p><p>College of Computer Studies Part VII. Development Environment Plan</p><p>Tool or Software Purpose in the Project</p><p>Operating System: Windows 11</p><p>Main development operating system used for programming, Unity development, asset creation, testing, documentation, and project management.</p><p>IDE / Code Editor: Visual Studio Code</p><p>Used to write, edit, organize, and debug C# scripts used by the game.</p><p>Programming Language: C#</p><p>Used to create player controls, game logic, educational activities, UI systems, progress systems, mini-games, and other gameplay features.</p><p>Framework / Engine: Unity</p><p>Primary game engine used to build the 3D world, scenes, UI, physics, animations, audio, Android builds, and other game systems.</p><p>Version Control: Git and GitHub</p><p>Used to manage project versions, track changes, back up source code, and support collaboration during development.</p><p>Database Tool: Not Applicable</p><p>The current version does not require a traditional database or server. Local user data and progress will be stored using JSON files.</p><p>Testing / Monitoring: Unity Profiler and Android Devices</p><p>Unity Profiler will be used to monitor CPU, GPU, memory, rendering, and performance. Actual Android smartphones and tablets will be used for real-device testing.</p><p>Design / Documentation: Figma</p><p>Used for planning UI/UX layouts, menus, game interfaces, user flows, and other interface designs before implementation in Unity.</p><p>Other Tool: Adobe Photoshop</p><p>Used to create, edit, resize, compress, and optimize 2D graphics, textures, icons, and visual assets.</p><p>Other Tool: Blender</p><p>Used to create, edit, optimize, and export lightweight 3D models and assets for Unity.</p><p>Why are these tools appropriate for your proposed project? The selected development stack establishes an efficient, reliable pipeline specifically suited for mobile educational game development. Unity and C# serve as the primary game engine framework, offering cross-platform compilation, physics handling, and rendering controls needed for the 3D top-down environment and 2D puzzle mechanics. Visual Studio Code facilitates clean script editing and debugging, while Git and GitHub ensure project stability and version tracking throughout development.</p><p>P a g e | 10</p><p>University of Perpetual Help System Laguna - JONELTA</p><p>College of Computer Studies</p><p>For asset production, Blender allows the team to model low-poly 3D assets with controlled polygon counts, while Figma and Adobe Photoshop enable the creation of child-friendly UI layouts and compressed 2D sprite atlases. Finally, utilizing the Unity Profiler alongside physical Android test devices ensures that runtime memory usage, draw calls, and touch responsiveness are benchmarked directly on target hardware rather than high-end development computers.</p><p>Part VIII. Technical Feasibility Conclusion At this preliminary milestone, Chainy is technically viable for development, provided that development parameters remain tightly scoped and tailored to the hardware profile of our target audience. The primary technical strength of this system lies in its standalone, offline-first design. By packaging the 3D learning modules, interactive puzzle mechanics, and progress tracking directly on the device, the game operates independently of remote database servers and high-speed internet, making it well-suited for deployments in partner community mini-libraries. Selecting Android further enhances accessibility by allowing the application to reach students across a wide range of affordable mobile hardware. The most significant technical challenge involves managing runtime 3D rendering and memory footprint on entry-level mobile chipsets. Unoptimized low-poly geometry, uncompressed textures, real-time lighting calculations, or unpooled object instantiation can quickly exhaust volatile memory and overburden mobile graphics processors. While modern mid-range devices handle these tasks easily, our primary beneficiaries frequently rely on older or budget Android smartphones and tablets. Without proactive asset optimization, the application risks thermal throttling, frame rate drops below 30 frames per second, delayed touch inputs, or unexpected memory-related terminations. To mitigate these risks before entering full production, our development workflow will establish strict asset budgets for 3D polygon counts, rely exclusively on pre-baked lightmaps, and compress user interface and texture atlases to mobile standards. Furthermore, we will build a vertical-slice prototype and conduct performance profiling using the Unity Profiler directly on physical budget Android test units. Based on this technical evaluation, the project should continue into active development. The team will prioritize constructing a streamlined Minimum Viable Product focusing strictly on the three foundational learning tracks blockchain validation, tamper detection, and artificial intelligence data classification while deferring secondary cloud-based features and educator analytics to subsequent development milestones.</p></div>',1)])])}const g=i(n,[["render",r]]);export{m as __pageData,g as default};
